	// Initialize a hash map to keep track of the divisibility status of each number
	Map<Integer, Boolean> divisibility = new HashMap<>();
	for (int num : arr) {
		divisibility.put(num, num % k == 0);
	}

	// Iterate through the array and calculate the sum of each pair
	for (int i = 0; i < arr.length - 1; i++) {
		int sum = arr[i] + arr[i + 1];
		if (sum % k == 0) {
			// If the sum is divisible by k, mark the corresponding numbers as divisible
			divisibility.put(arr[i], true);
			divisibility.put(arr[i + 1], true);
		}
	}

	// Check if all numbers are divisible by k
	for (Boolean val : divisibility.values()) {
		if (!val) {
			return false;
		}
	}
	return true;
}

